    binary_override=binary;struct Server *s=start("1",NULL);diagnostic(compile(s,source),"A205",1);last[1]='1';save_bytes(catalog,bytes,size);char *id=handle(compile(s,source));output(s,id,"4",5);released(s,id);free(id);stop(s);
